{
  "technical_and_design_decisions": [
    "Multi-tenant namespace isolation (U1) will be implemented via a configurable ZooKeeper namespace prefix derived from the active tenant profile, with backward compatibility for the default namespace.",
    "Admin server authentication (U2) will use Spring Security's interactive authentication (username/password) replacing the previous file-based credential mechanism, with credentials held in memory only and not written to disk or logs.",
    "Maintenance branch (U3) will follow GitFlow conventions, branching from the latest MINOR release tag (e.g. 1.0.x) and protected for MINOR-only commits.",
    "Deprecated function cleanup (U4) will be done in a single refactoring pass focused on the module registry download path, plus targeted cleanups in Shell and Admin-UI modules.",
    "xd-shell random port access (U5) will be implemented by reading the admin server's actual port from ZooKeeper (where it is registered at startup) rather than relying on a hard-coded port or requiring a load balancer.",
    "Kafka consumer upgrade (U6) will adopt the Kafka 0.9 Consumer Rewrite API and rerun the existing test suite, fixing any compatibility breaks.",
    "Audio/video streaming (U7) is scoped strictly as a research spike (Motion-JPEG feasibility and design specs); no production implementation is in scope for this increment.",
    "Message rates toggle (U8) will add a boolean 'messageRatesEnabled' flag to servers.yml consumed by the cluster view component to suppress rate computation and rendering.",
    "All work will be performed against a Spring Framework 6.x baseline requiring Java 17+ as stated in the spec context."
  ],
  "assumptions": [
    "The codebase is a Spring-based distributed system (consistent with Spring XD/Data Flow references: xd-shell, ZooKeeper, Admin server, Kafka, HDFS).",
    "The developer has working familiarity with the existing modules; no ramp-up/onboarding time is included in the per-activity estimates.",
    "Unit and integration tests are part of each implementation activity; only cross-cutting integration testing is broken out separately.",
    "U7 (audio/video) is treated as a research/design spike only — production code and full implementation are explicitly out of scope per the 'Spike scope' note.",
    "U3 (maintenance branch) is a one-time Git/repo configuration task, not an ongoing process.",
    "No third-party procurement, security review, or stakeholder approval cycles are included.",
    "Documentation effort covers brief developer-facing notes per story; user-facing documentation overhaul is not included.",
    "Estimates assume a single experienced developer performing all work; no coordination overhead between multiple developers is added.",
    "All estimates are in work-hours of focused development effort (not elapsed calendar time)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and design (all stories)",
      "activity_description": "Review all 8 user stories, produce a short technical design note for each, and confirm the scope of U7 as a spike-only deliverable.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Tenant-aware ZooKeeper namespace: design",
      "activity_description": "Design the tenant profile model and how it maps to a ZK namespace prefix; ensure backward compatibility with the default namespace.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Tenant-aware ZooKeeper namespace: implementation",
      "activity_description": "Add tenant-aware ZK client configuration, plumb the namespace through the metadata service, and update relevant bootstrap code.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Tenant-aware ZooKeeper namespace: testing",
      "activity_description": "Write unit and integration tests covering tenant isolation and default-namespace fallback behavior.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Interactive admin authentication: design",
      "activity_description": "Design the interactive credential flow for the admin server and how xd-shell will prompt the user and cache the session.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Interactive admin authentication: implementation",
      "activity_description": "Replace file-based credential loading with interactive username/password prompting, configure Spring Security on the admin server, and ensure credentials are never written to logs or disk.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "U2 - Interactive admin authentication: testing",
      "activity_description": "Test successful login, failed login, credential redaction in logs, and shell-side prompting behavior.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "U3 - Maintenance branch setup",
      "activity_description": "Create the MINOR release maintenance branch (e.g. 1.0.x) from the appropriate tag, configure branch protection for MINOR-only commits.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "U4 - Identify deprecated functions",
      "activity_description": "Inventory deprecated APIs/paths (e.g. module definition download) and list Shell and Admin-UI cleanup targets.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "U4 - Remove deprecated module definition download",
      "activity_description": "Delete the module definition download code paths and any related configuration and references.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A11",
      "activity_name": "U4 - Clean up Shell and Admin-UI modules",
      "activity_description": "Remove deprecated calls/UI elements from xd-shell and Admin-UI; update imports and references.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A12",
      "activity_name": "U4 - Testing and regression verification",
      "activity_description": "Run the full test suite and fix any callers broken by the deprecated function removal.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A13",
      "activity_name": "U5 - Research spike: ZK direct vs LB for xd-shell",
      "activity_description": "Investigate whether xd-shell should connect directly to ZooKeeper or via a load balancer; document trade-offs and HA/federation implications.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A14",
      "activity_name": "U5 - Design random port discovery",
      "activity_description": "Design the mechanism for xd-shell to retrieve the actual admin server port (chosen by Tomcat at startup) from ZK registration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A15",
      "activity_name": "U5 - Implement random port retrieval in xd-shell",
      "activity_description": "Update xd-shell to read the admin server's endpoint from ZK and connect to it; update Admin server registration if needed.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A16",
      "activity_name": "U5 - Testing random port access",
      "activity_description": "Test xd-shell connection when admin server picks a non-default port, and verify behavior under multiple instances.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A17",
      "activity_name": "U6 - Upgrade Kafka client to 0.9 consumer rewrite",
      "activity_description": "Update Kafka client dependency and migrate message bus code to the new consumer API.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A18",
      "activity_name": "U6 - Fix failing tests after Kafka upgrade",
      "activity_description": "Rerun the full Kafka-related test suite and fix compile/runtime/test failures introduced by the new consumer API.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A19",
      "activity_name": "U6 - Verification pass",
      "activity_description": "End-to-end verification that the Kafka message bus still functions correctly with the upgraded client.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A20",
      "activity_name": "U7 - Research Motion-JPEG feasibility (spike)",
      "activity_description": "Investigate Motion-JPEG streaming feasibility, alternative codecs, opencv compatibility, and platform constraints.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A21",
      "activity_name": "U7 - Design specs for audio/video ingest (spike)",
      "activity_description": "Produce a design document for an audio/video ingest pipeline suitable for facial-detection analytics.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A22",
      "activity_name": "U8 - Add messageRatesEnabled config flag",
      "activity_description": "Add the boolean 'messageRatesEnabled' option to servers.yml and wire it through configuration loading to the cluster view component.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A23",
      "activity_name": "U8 - Update cluster view rendering",
      "activity_description": "Conditionally skip rate computation and rendering in the cluster view when the flag is disabled.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A24",
      "activity_name": "U8 - Testing the toggle",
      "activity_description": "Verify the cluster view behavior with the flag enabled and disabled.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A25",
      "activity_name": "Cross-cutting integration testing",
      "activity_description": "Run end-to-end integration tests across modules to verify the changes from U1, U2, U4, U5, U6, and U8 do not regress each other.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A26",
      "activity_name": "Developer documentation updates",
      "activity_description": "Update configuration, tenant, and admin authentication notes in developer docs to reflect the new behavior.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A27",
      "activity_name": "Code review and final merge",
      "activity_description": "Peer-style self review of all changes, final cleanups, and merging into the appropriate branches.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 173
  }
}
